const { generateWelcomeCard, parseArgs } = require('./src/welcome');
const { ytmp3, ytmp4, search, playmp3, playmp4, transcript } = require('./src/youtube');
const { saveweb2zip } = require('./src/web2zip');
const { instadl } = require('./src/instagram');
const { fetchNews, categories, getSiteList, fetchGroup } = require('./src/news');
const { pinterest } = require('./src/pinterest');
const mova = require('./src/mova'); // Direct import as mova

// Initialize mova features
mova.init();

// Enhanced CLI entry point with ASCII art welcome and colored logs
if (require.main === module) {
  // Print welcome ASCII art with color
  mova.printArt('welcome', 'brightCyan');
  mova.println('Welcome to MoVanest! A multi-tool CLI for media, news, and more.', { color: 'brightGreen' });

  const options = parseArgs();
  generateWelcomeCard(options)
    .then(buffer => {
      const fs = require('fs');
      fs.writeFileSync(options.output, buffer);
      mova.println(`Welcome card generated: ${options.output}`, { color: 'brightBlue' });
    })
    .catch(err => {
      mova.println('Error:', { color: 'red' });
      mova.println(err.message, { color: 'red' });
      process.exit(1);
    });
}


module.exports = {
  generateWelcomeCard,
  search,
  ytmp3,
  ytmp4,
  saveweb2zip,
  instadl,
  fetchNews,
  categories,
  getSiteList,
  fetchGroup,
  pinterest,
  // Mova exports for user access (now includes init and more for completeness)
  mova: {
    println: mova.println,
    printArt: mova.printArt,
    addArt: mova.addArt,
    COLORS: mova.COLORS,
    options: mova.options,
    init: mova.init, 
    fromString: mova.fromString,  
    rainbow: mova.rainbow 
  }
};
